          is_low_version = is_low_version,
          rival_user_id = rival_user_id,
          rival_room_id = rival_room_id,
          is_initiator = is_initiator,
          linkmic_id_str = linkmic_id_str,
          best_teammate_uid = best_teammate_uid,
          has_topic_perm = has_topic_perm,
          inner_channel_id = inner_channel_id,
          unknownFields = unknownFields
        )
      }

      override fun redact(`value`: CohostListUser): CohostListUser = value.copy(
        avatar_thumb = value.avatar_thumb?.let(ImageModel.ADAPTER::redact),
        unknownFields = ByteString.EMPTY
      )
    }

    private const val serialVersionUID: Long = 0L
  }
}
